"""Persistent graph process fixture; inputs and state paths are generated by tests."""

import asyncio
import sys
from typing import TypedDict

from langgraph.checkpoint.sqlite.aio import AsyncSqliteSaver
from langgraph.graph import StateGraph, START, END

from agent.langgraph import GraphContext, LangGraphAgent
from oea.stdio import run_agent_async


class State(TypedDict, total=False):
    input: str
    count: int
    log: list[str]


async def main():
    async with AsyncSqliteSaver.from_conn_string(sys.argv[1]) as saver:
        def step(state):
            return {"count": state.get("count", 0) + 1, "log": [*state.get("log", []), state["input"]]}
        graph = (StateGraph(State, context_schema=GraphContext).add_node("step", step)
                 .add_edge(START, "step").add_edge("step", END).compile(checkpointer=saver))
        adapter = LangGraphAgent("graph", graph, input_builder=lambda request: request.payload,
            output_builder=lambda state: {"text": "Graph step completed", "count": state["count"], "log": state["log"]},
            fork_builder=lambda state: {"count": state["count"], "log": state["log"]}, managed_context=True)
        await run_agent_async(adapter)


if __name__ == "__main__":
    asyncio.run(main())
